CREATE OR REPLACE FUNCTION nexus.canary_query_ring_upsert(
    p_tenant      text,
    p_collections text[],
    p_models      text[],
    p_vectors     text[],
    p_digests     bytea[]
) RETURNS integer
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_n       integer := coalesce(cardinality(p_digests), 0);
    v_written integer := 0;
    v_vec     nexus.vector;
    v_dims    integer;
    v_rings   text[]  := ARRAY[]::text[];
    v_ring    text;
    i         integer;
BEGIN
    IF coalesce(cardinality(p_collections), 0) <> v_n
       OR coalesce(cardinality(p_models), 0)  <> v_n
       OR coalesce(cardinality(p_vectors), 0) <> v_n THEN
        RAISE EXCEPTION 'canary_query_ring_upsert: the four arrays must have the same length'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    FOR i IN 1 .. v_n LOOP
        CONTINUE WHEN p_collections[i] IS NULL OR p_models[i] IS NULL
                      OR p_digests[i] IS NULL OR p_vectors[i] IS NULL;
        v_vec  := p_vectors[i]::nexus.vector;
        v_dims := nexus.vector_dims(v_vec);
        CONTINUE WHEN v_dims NOT IN (384, 768, 1024);
        BEGIN
            IF v_dims = 384 THEN
                INSERT INTO nexus.canary_query_ring
                    (tenant_id, collection, embedding_model, embedding_384, vector_digest, added_at)
                VALUES (p_tenant, p_collections[i], p_models[i], v_vec, p_digests[i], clock_timestamp())
                ON CONFLICT (tenant_id, collection, vector_digest)
                DO UPDATE SET added_at = EXCLUDED.added_at;
            ELSIF v_dims = 768 THEN
                INSERT INTO nexus.canary_query_ring
                    (tenant_id, collection, embedding_model, embedding_768, vector_digest, added_at)
                VALUES (p_tenant, p_collections[i], p_models[i], v_vec, p_digests[i], clock_timestamp())
                ON CONFLICT (tenant_id, collection, vector_digest)
                DO UPDATE SET added_at = EXCLUDED.added_at;
            ELSE
                INSERT INTO nexus.canary_query_ring
                    (tenant_id, collection, embedding_model, embedding_1024, vector_digest, added_at)
                VALUES (p_tenant, p_collections[i], p_models[i], v_vec, p_digests[i], clock_timestamp())
                ON CONFLICT (tenant_id, collection, vector_digest)
                DO UPDATE SET added_at = EXCLUDED.added_at;
            END IF;
            v_written := v_written + 1;
            v_rings   := v_rings || p_collections[i];
        EXCEPTION WHEN foreign_key_violation THEN
            -- S6: the collection (or its model) is gone since the entry was enqueued. Skip this entry only.
            NULL;
        END;
    END LOOP;

    -- Trim each ring this call wrote to, in a fixed order (two concurrent calls take the same row locks in the
    -- same order): keep the 32 newest by added_at (ties on the digest), and nothing older than 30 days.
    FOR v_ring IN SELECT u.r FROM unnest(v_rings) AS u(r) GROUP BY u.r ORDER BY u.r LOOP
        DELETE FROM nexus.canary_query_ring d
         WHERE d.tenant_id = p_tenant
           AND d.collection = v_ring
           AND (d.added_at < clock_timestamp() - interval '30 days'
                OR d.vector_digest NOT IN (
                       SELECT k.vector_digest
                         FROM nexus.canary_query_ring k
                        WHERE k.tenant_id = p_tenant
                          AND k.collection = v_ring
                        ORDER BY k.added_at DESC, k.vector_digest
                        LIMIT 32));
    END LOOP;

    RETURN v_written;
END;
$fn$;

GRANT EXECUTE ON FUNCTION nexus.canary_query_ring_upsert(text, text[], text[], text[], bytea[]) TO nexus_svc;
